// Builds src/legal/policy-texts.generated.ts from the approved policy texts in docs/legal/.
// The markdown files are the record counsel approved; the app shows exactly their words.
// Only the small subset the policies use is accepted (## headings, paragraphs, - and 1. lists,
// pipe tables, **bold**, `code`, [text](https://...)); anything else fails loudly.
// `--check` fails if the generated file is out of date, without writing.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

/** The approved version of each policy, matching identity's CURRENT_POLICIES. */
const VERSIONS = { terms: 'terms-2026-11-26', privacy: 'privacy-2026-11-26' };

const legalDir = path.resolve(import.meta.dirname, '../../../docs/legal');
const target = path.resolve(import.meta.dirname, '../src/legal/policy-texts.generated.ts');

function fail(file, line, message) {
  throw new Error(`${file}:${String(line)}: ${message}`);
}

/** **bold**, `code` and [text](https://...) inside a line. */
function inline(text, file, line) {
  const spans = [];
  const pattern = /\*\*([^*]+)\*\*|`([^`]+)`|\[([^\]]+)\]\(([^)\s]+)\)/g;
  let last = 0;
  for (const match of text.matchAll(pattern)) {
    if (match.index > last) spans.push({ t: 'text', v: text.slice(last, match.index) });
    if (match[1] !== undefined) spans.push({ t: 'b', v: match[1] });
    else if (match[2] !== undefined) spans.push({ t: 'code', v: match[2] });
    else {
      if (!match[4].startsWith('https://')) fail(file, line, 'links must be https');
      spans.push({ t: 'link', v: match[3], href: match[4] });
    }
    last = match.index + match[0].length;
  }
  if (last < text.length) spans.push({ t: 'text', v: text.slice(last) });
  for (const span of spans) {
    if (/[*`]|\]\(/.test(span.v)) fail(file, line, `unsupported markdown in "${span.v}"`);
  }
  return spans;
}

const cells = (row) =>
  row
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split('|')
    .map((cell) => cell.trim());

function parse(file, markdown) {
  const lines = markdown.split('\n');
  const blocks = [];
  let title;
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const n = i + 1;
    if (line.trim() === '') {
      i += 1;
    } else if (line.startsWith('# ')) {
      if (title !== undefined) fail(file, n, 'only one # title');
      title = line.slice(2).trim();
      i += 1;
    } else if (line.startsWith('Version `')) {
      i += 1; // the page prints the version line from the policy record
    } else if (line.startsWith('## ')) {
      blocks.push({ t: 'h2', c: inline(line.slice(3).trim(), file, n) });
      i += 1;
    } else if (line.startsWith('- ') || /^\d+\. /.test(line)) {
      const ordered = !line.startsWith('- ');
      const items = [];
      while (i < lines.length && (ordered ? /^\d+\. / : /^- /).test(lines[i])) {
        items.push(inline(lines[i].replace(ordered ? /^\d+\. / : /^- /, ''), file, i + 1));
        i += 1;
      }
      blocks.push({ t: ordered ? 'ol' : 'ul', items });
    } else if (line.startsWith('|')) {
      const head = cells(line);
      if (!/^\|( *---+ *\|)+$/.test(lines[i + 1] ?? '')) fail(file, n + 1, 'table needs a --- row');
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].startsWith('|')) {
        const row = cells(lines[i]);
        if (row.length !== head.length) fail(file, i + 1, 'row has the wrong number of cells');
        rows.push(row.map((cell) => inline(cell, file, i + 1)));
        i += 1;
      }
      blocks.push({
        t: 'table',
        head: head.map((cell) => inline(cell, file, n)),
        rows,
      });
    } else if (/^(#|>|```|\* |\+ )/.test(line)) {
      fail(file, n, 'unsupported markdown block');
    } else {
      blocks.push({ t: 'p', c: inline(line.trim(), file, n) });
      i += 1;
    }
  }
  if (title === undefined) fail(file, 1, 'missing # title');
  return { title, blocks };
}

const texts = {};
for (const [policy, version] of Object.entries(VERSIONS)) {
  const file = path.join(legalDir, `${version}.md`);
  const source = readFileSync(file, 'utf8');
  if (!source.includes(`Version \`${version}\``))
    fail(file, 3, `must state Version \`${version}\``);
  texts[policy] = { version, ...parse(path.relative(process.cwd(), file), source) };
}

const ts = `// Generated by scripts/legal-gen.mjs from docs/legal/. Do not edit.\n\nimport type { PolicyText } from './policy-blocks';\n\nexport const POLICY_TEXTS: Readonly<Record<'terms' | 'privacy', PolicyText>> = ${JSON.stringify(texts, null, 2)};\n`;

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    // missing counts as stale
  }
  if (current !== ts) {
    process.stderr.write(
      'src/legal/policy-texts.generated.ts is out of date: run pnpm legal:gen\n',
    );
    process.exit(1);
  }
} else {
  writeFileSync(target, ts);
}
